 async function page(bearer){let abandoned=false;const creating=browser.createBrowserContext();creating.then(c=>{if(abandoned)c.close().catch(()=>{});},()=>{});let context;try{context=await ui(()=>creating);}catch(error){abandoned=true;throw error;}contexts.push(context);const p=await ui(()=>context.newPage());p.on('response',record);await ui(()=>configureFreshPage(p));await p.evaluateOnNewDocument(t=>localStorage.setItem('token',t),bearer);await p.setRequestInterception(true);p.on('request',r=>{let allowed=false;try{const u=new URL(r.url());allowed=u.origin===origin||['data:','about:','blob:'].includes(u.protocol);if(u.origin===origin&&u.pathname.startsWith('/api/')){requests++;allowed=allowed&&requests<=1500&&!/\/chat$/.test(u.pathname);}}catch{}(allowed?r.continue():r.abort()).catch(()=>{});});return p;}
 async function api(p,url,method='GET',body){return ui(()=>p.evaluate(async({url,method,body})=>{const r=await fetch(url,{method,headers:{Authorization:'Bearer '+localStorage.getItem('token'),'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const raw=await r.text();if(raw.length>1024*1024)throw Error('Response cap');return {status:r.status,body:JSON.parse(raw)};},{url,method,body}));}
 const successful=async(...args)=>{const r=await api(...args);assert.equal(r.status,200);return r.body;};
 async function workshop(p,completed){stage='workshop';checkpoint();await ui(()=>p.goto(origin+'/workshop/supply-chain',{waitUntil:'domcontentloaded'}));const snap=await successful(p,'/api/workshop/config/snapshot');const cfg=snap.exercises[KEY];const expected=IDS.filter(id=>cfg.objectives[id].isVisible).map(id=>({id,label:cfg.objectives[id].label,completed:completed.includes(id),hintVisible:cfg.objectives[id].hintVisible,solutionVisible:cfg.objectives[id].solutionVisible}));await ui(()=>p.waitForFunction(objectiveRowsMatch,{},expected));trace.push({kind:'workshop',expected});return expected;}
 async function instructor(admin){stage='instructor';checkpoint();await ui(()=>admin.goto(origin+'/admin/student-workshop-view',{waitUntil:'domcontentloaded'}));await ui(()=>admin.waitForSelector('select option[value="'+studentId+'"]'));const w=wait(admin,'/api/admin/student-workshop-view/'+studentId);assert.deepEqual(await ui(()=>admin.select('select',String(studentId))),[String(studentId)]);const body=await consume(w);assert.equal(body.student.id,studentId);const row=project(body.challenges);await ui(()=>admin.waitForSelector('details[aria-label='+JSON.stringify('Objective progress: '+row.name)+']'));await ui(()=>admin.click('details[aria-label='+JSON.stringify('Objective progress: '+row.name)+'] summary'));await ui(()=>admin.waitForFunction(instructorRowsMatch,{},{...row,aggregate:[row.completedObjectiveCount+'/'+row.objectiveCount+' objectives',timeText(row.timeSpentSeconds),'Hints: '+row.objectives.filter(x=>x.hintVisible).length,'Solutions: '+row.objectives.filter(x=>x.solutionVisible).length]}));trace.push({kind:'instructor',row});}
 async function editors(admin,{key=KEY,ids=IDS,route='supply-chain-workshop'}={}){stage='editors';checkpoint();
  await ui(()=>admin.goto(origin+'/admin/solutions',{waitUntil:'domcontentloaded'}));await ui(()=>admin.waitForSelector('[data-exercise-key="'+key+'"]'));
  assert.equal(new URL(admin.url()).pathname,'/admin/exercises');await ui(()=>admin.$eval('[data-exercise-key="'+key+'"]',e=>[...e.querySelectorAll('button')].find(x=>x.textContent.includes('Manage Objectives')).click()));
  for(const id of ids){stage='editors:'+id+':original';checkpoint();const endpoint='/api/admin/'+route+'/solutions/preview/'+id;const original=(await successful(admin,endpoint)).solution;if(key===KEY&&id==='pkg_discover')assert.equal(original.approach,expectedDefaults.packageApproach);
   for(const title of [original.title+' [owned parity]',original.title]){stage='editors:'+id+':open';checkpoint();const preview=wait(admin,endpoint);await ui(()=>clickVisibleEditor(admin,id));const loaded=(await consume(preview)).solution;await ui(()=>admin.waitForFunction(solutionEditorMatches,{},loaded));
    stage='editors:'+id+':edit';checkpoint();const handle=await ui(()=>admin.evaluateHandle(()=>[...document.querySelectorAll('label')].find(e=>e.textContent.trim()==='Objective Title').parentElement.querySelector('input')));const proof={id,target:titleProof(title,title),dom:null,sent:null,readback:null};titleDiagnostics.push(proof);checkpoint();try{await ui(()=>replaceEditorTitle(handle.asElement(),title,value=>{proof.dom=titleProof(value,title);checkpoint();}));}finally{await handle.dispose();}
    stage='editors:'+id+':save';checkpoint();const saved=wait(admin,'/api/admin/'+route+'/solutions/'+id);await ui(()=>admin.evaluate(()=>[...document.querySelectorAll('button')].find(e=>e.textContent.trim()==='Save Changes').click()));await consume(saved,response=>{const raw=response.request().postData();if(typeof raw==='string'&&Buffer.byteLength(raw)<=1048576){const patch=JSON.parse(raw);assertEditorPatch(patch,title);proof.sent=titleProof(patch.title,title);}checkpoint();assert.equal(proof.sent?.matchesTarget,true);});stage='editors:'+id+':closed';checkpoint();await ui(()=>admin.waitForFunction(solutionEditorAbsent));stage='editors:'+id+':readback';checkpoint();const actual=(await successful(admin,endpoint)).solution;proof.readback=titleProof(actual.title,title);checkpoint();assert.equal(actual.title,title);for(const key of ['approach','examples','tips','hints','difficulty'])assert.deepEqual(actual[key],original[key]);
   }trace.push({kind:'solution-editor',workshopKey:key,id,readAndSaveRestored:true});
  }
 }
 async function totals(p,done,total){for(const route of ['/workshop-dashboard','/workshop/challenges','/workshop/progress']){stage='totals:'+route;checkpoint();const w=wait(p,'/api/workshop/challenges');await ui(()=>p.goto(origin+route,{waitUntil:'domcontentloaded'}));const body=await consume(w);const rows=body.challenges||body;const row=project(rows);assert.equal(row.completedObjectiveCount??row.objectives.filter(x=>x.completed).length,done);assert.equal(row.objectiveCount??row.objectives.length,total);await ui(()=>p.waitForFunction(aggregateMatches,{},{name:row.name||row.title,done,total,time:row.timeSpentSeconds>0?timeText(row.timeSpentSeconds,route==='/workshop/challenges'):null,challenge:route==='/workshop/challenges'}));if(route==='/workshop/progress')assert.equal(new URL(p.url()).pathname,'/workshop-dashboard');trace.push({kind:'totals',route,row});}}
 try{
  const learner=await page(token),sibling=await page(siblingToken),admin=await page(adminToken);
  const fresh=await workshop(learner,IDS);assert.equal(fresh.find(x=>x.id==='tool_list').label,expectedDefaults.toolLabel);await workshop(sibling,[]);await ui(()=>admin.goto(origin+'/admin/exercises'));
  assert.equal((await api(learner,'/api/admin/exercises')).status,403);await ui(()=>admin.waitForSelector('[data-exercise-key="'+KEY+'"]'));await ui(()=>admin.$eval('[data-exercise-key="'+KEY+'"]',e=>{const b=[...e.querySelectorAll('button')].find(x=>x.textContent.includes('Manage Objectives'));if(!b)throw Error('Missing objective controls');b.click();}));await ui(()=>admin.waitForFunction(ids=>ids.every(id=>document.querySelector('[data-objective-id="'+id+'"] [data-control="visible"]'))&&document.querySelectorAll('[data-objective-id]').length===ids.length,{},IDS));
  await successful(admin,'/api/admin/exercises/'+KEY+'/solutions','PATCH',{enabled:true});
  await workshop(learner,IDS);const packageSolution=(await successful(learner,'/api/solutions/supply-chain/pkg_discover')).solution;assert.equal(packageSolution.approach,expectedDefaults.packageApproach);
  await ui(()=>learner.evaluate(expectedLabel=>{const label=[...document.querySelectorAll('.objectives-list .obj-name')].find(e=>e.textContent===expectedLabel);const card=label?.closest('.obj-content')?.parentElement;const button=[...card.querySelectorAll('button')].find(b=>b.textContent.trim()==='View Solution');button.click();},fresh.find(x=>x.id==='pkg_discover').label));
  await ui(()=>learner.waitForFunction(renderedApproachMatches,{},{title:packageSolution.title,approach:expectedDefaults.packageApproach}));
  await ui(()=>learner.evaluate(title=>{const heading=[...document.querySelectorAll('h3')].find(e=>e.textContent==='Solution: '+title);heading.parentElement.querySelector('button').click();},packageSolution.title));trace.push({kind:'fresh-curriculum-content',labelExact:true,approachExact:true});
  await editors(admin);await editors(admin,DPI_EDITOR);await totals(learner,6,6);await totals(sibling,0,6);await instructor(admin);
  for(const id of IDS){
   await successful(admin,'/api/admin/exercises/'+KEY+'/objectives/'+id,'PATCH',{enabled:false});await workshop(learner,IDS);await totals(learner,5,5);
   await successful(admin,'/api/admin/exercises/'+KEY+'/objectives/'+id,'PATCH',{enabled:true});
  }
  for(const [hint,solution] of [[true,false],[false,true],[true,true],[false,false]]){
   await successful(admin,'/api/admin/exercises/'+KEY+'/hints','PATCH',{enabled:hint});await successful(admin,'/api/admin/exercises/'+KEY+'/solutions','PATCH',{enabled:solution});
   await workshop(learner,IDS);await instructor(admin);
   for(const id of IDS){const snapshot=(await successful(admin,'/api/workshop/config/snapshot')).exercises[KEY].objectives[id];assert.equal(snapshot.hintVisible,hint&&snapshot.hasHintContent);assert.equal(snapshot.solutionVisible,solution&&snapshot.hasSolutionContent);if(!snapshot.hintVisible)assert.notEqual((await api(learner,'/api/hints/'+KEY+'/'+id)).status,200);if(!snapshot.solutionVisible)assert.notEqual((await api(learner,'/api/solutions/supply-chain/'+id)).status,200);}
  }
  await successful(admin,'/api/admin/exercises/'+KEY+'/hints','PATCH',{enabled:true});await successful(admin,'/api/admin/exercises/'+KEY+'/solutions','PATCH',{enabled:true});
  for(const [hint,solution] of [[false,true],[true,false]]){for(const id of IDS){await successful(admin,'/api/admin/exercises/'+KEY+'/objectives/'+id+'/hint','PATCH',{enabled:hint});await successful(admin,'/api/admin/exercises/'+KEY+'/objectives/'+id+'/solution','PATCH',{enabled:solution});}const rows=await workshop(learner,IDS);assert(rows.every(x=>x.hintVisible===hint&&x.solutionVisible===solution));await instructor(admin);}
  for(const kind of ['hint','solution']){assert.equal(typeof withAbsentContent,'function');await withAbsentContent(kind,async()=>{const rows=await workshop(learner,IDS);assert(rows.every(x=>x[kind+'Visible']===false));for(const id of IDS){const cfg=(await successful(admin,'/api/workshop/config/snapshot')).exercises[KEY].objectives[id];assert.equal(cfg[kind==='hint'?'hasHintContent':'hasSolutionContent'],false);assert.notEqual((await api(learner,kind==='hint'?'/api/hints/'+KEY+'/'+id:'/api/solutions/supply-chain/'+id)).status,200);}await instructor(admin);});}
  await workshop(learner,IDS);await instructor(admin);await totals(learner,6,6);await totals(sibling,0,6);
  await ui(()=>learner.screenshot({path:path.join(evidence,'codebot-current-learner.png'),fullPage:true}));await ui(()=>admin.screenshot({path:path.join(evidence,'codebot-current-instructor.png'),fullPage:true}));
  return {scope:'controlled-projection-only',modelCalls:0,earnedCredit:false,allSix:IDS,requests,trace};
 }finally{for(const w of waits)w.controller.abort();await Promise.allSettled([...waits].map(x=>x.promise));const closed=await settleOwnership(contexts.map((c,i)=>['context'+i,()=>c.close()]),5000);assert(closed.every(x=>x.status==='fulfilled'),'Context cleanup incomplete');}
