const OBJECTIVE_CONTENT_CASES=Object.freeze([
 Object.freeze({id:'xss_r1',workshopKey:'xss_workshop',challengeKey:'reflected_xss_llm',route:'xss-workshop'}),
 Object.freeze({id:'csrf_g1',workshopKey:'csrf_workshop',challengeKey:'csrf_prompt_injection',route:'csrf-workshop'}),
]);
const OBJECTIVE_CONTENT_FIELDS=Object.freeze({title:'Title',hint:'Hint',example:'Example Prompt / Payload',explanation:'Explanation (Why it works)'});
function objectiveContentRequestAllowed(url,origin,count){try{const u=new URL(url);return count<=400&&(u.origin===origin||['data:','about:','blob:'].includes(u.protocol))&&!/\/(chat|jsonrpc|complete|reset|reset-tab|agent-action)$/.test(u.pathname);}catch{return false;}}
function objectiveContentEditorMatches({id,values}){
 const headings=[...document.querySelectorAll('h2')].filter(e=>e.textContent==='Edit Objective Solution — '+id);if(headings.length!==1)return false;
 const root=headings[0].parentElement.parentElement,labels={title:'Title',hint:'Hint',example:'Example Prompt / Payload',explanation:'Explanation (Why it works)'};
 return Object.entries(values).every(([key,value])=>{const fields=[...root.querySelectorAll('label')].filter(e=>e.textContent===labels[key]).map(e=>e.parentElement.querySelector('input,textarea'));return fields.length===1&&fields[0].value===value;});
}
function objectiveContentModalMatches(expected){
 const dialogs=[...document.querySelectorAll('[role="dialog"]')].filter(e=>e.getAttribute('aria-modal')==='true');
 return dialogs.length===1&&[...dialogs[0].querySelectorAll('h2,h3')].some(e=>e.textContent===expected.title)&&[...dialogs[0].querySelectorAll('code')].some(e=>e.textContent===expected.example)&&[...dialogs[0].querySelectorAll('p')].some(e=>e.textContent===expected.explanation);
}
function assertObjectiveContentPatch(actual,expected){assert.deepEqual(Object.keys(actual).sort(),Object.keys(OBJECTIVE_CONTENT_FIELDS).sort());assert.deepEqual(actual,expected);}
function genericSolutionPatch(content,isPublic){return {solution_title:content.title,solution_description:content.description||'',solution_steps:content.hints||[],solution_code:content.code||'',explanation:content.approach||'',reference_links:content.references||[],difficulty_level:content.difficulty||'medium',estimated_time:content.estimatedTime||'',prerequisites:content.prerequisites||[],tags:content.tips||[],is_public:isPublic};}
function genericStoredPatch(p){return {title:p.solution_title,description:p.solution_description,hints:p.solution_steps,code:p.solution_code,approach:p.explanation,references:p.reference_links,difficulty:p.difficulty_level,estimatedTime:p.estimated_time,prerequisites:p.prerequisites,tips:p.tags};}
function genericEditorMatches(values){const h=[...document.querySelectorAll('h2')].filter(x=>x.textContent==='Edit Solution');if(h.length!==1)return false;return Object.entries(values).every(([label,value])=>{const labels=[...h[0].parentElement.parentElement.querySelectorAll('label')].filter(x=>x.textContent.trim()===label);return labels.length===1&&labels[0].parentElement.querySelector('input,textarea').value===value;});}
function genericSaveDiagnostic(payload,expected,status,response){
 const messages=['Invalid content patch','Invalid content list','Invalid content text','Invalid solution examples','Invalid optional solution text','Invalid optional solution list','Invalid solution reference','isPublic must be a boolean','enabled must be a boolean'];
 const keys=payload&&typeof payload==='object'&&!Array.isArray(payload)?Object.keys(payload).sort():[];
 const allowed=Object.keys(expected);return {stage:'generic-save-response',status,payloadMatches:require('node:util').isDeepStrictEqual(payload,expected),unexpectedKeyCount:keys.filter(k=>!allowed.includes(k)).length,fields:keys.filter(k=>allowed.includes(k)).map(key=>{const v=payload[key];return {key,matchesExpected:require('node:util').isDeepStrictEqual(v,expected[key]),type:v===null?'null':Array.isArray(v)?'array':typeof v,...(typeof v==='string'?{empty:v.length===0,blank:v.trim().length===0}:Array.isArray(v)?{empty:v.length===0,allNonblankStrings:v.every(x=>typeof x==='string'&&x.trim().length>0)}:{})};}),errorCode:['BAD_REQUEST','NOT_FOUND','OBJECTIVE_UNQUALIFIED','EXERCISE_NOT_READY'].includes(response?.code)?response.code:null,errorMessage:messages.includes(response?.error)?response.error:null};
}
async function qualifyGenericSolutionCase({item,admin,learner,origin,work,read,gateSnapshot,api,migration,initial,record}){
 const original=await work(()=>read(item)),gates=await work(gateSnapshot),enabled=gates.objectives.find(x=>x.objective_id===item.id).solution_enabled;
 const base=genericSolutionPatch(original,enabled),custom={...base,solution_title:'Owned generic solution title',solution_description:'Owned generic solution description'};
 const initialRows=(await api(admin,'/api/admin/solutions')).solutions.filter(x=>x.id===item.workshopKey+':'+item.id);assert.equal(initialRows.length,1);record({stage:'generic-get-content',explanationMatches:initialRows[0].explanation===original.approach,explanationNonempty:typeof initialRows[0].explanation==='string'&&!!initialRows[0].explanation.trim()});assert.equal(initialRows[0].explanation,original.approach);
 const endpoint='/api/admin/solutions/'+item.workshopKey+':'+item.id,selector='[data-objective-id="'+item.id+'"] button[title="Edit Solution"]';
 for(const patch of [custom,base]){
  await work(()=>admin.waitForSelector(selector,{visible:true}));await work(()=>admin.$eval(selector,e=>e.scrollIntoView({block:'center'})));await work(()=>admin.waitForFunction(editorTargetUnobstructed,{},selector));await work(()=>admin.click(selector));
  const values={'Solution Title *':patch.solution_title,Description:patch.solution_description};await work(()=>admin.waitForFunction(()=>[...document.querySelectorAll('h2')].filter(e=>e.textContent==='Edit Solution').length===1));const initialValues={'Solution Title *':patch===custom?base.solution_title:custom.solution_title,Description:patch===custom?base.solution_description:custom.solution_description,Explanation:base.explanation};try{await work(()=>admin.waitForFunction(genericEditorMatches,{},initialValues));}catch(error){const matches={};for(const [label,value]of Object.entries(initialValues))matches[label]=await work(()=>admin.evaluate(genericEditorMatches,{[label]:value})).catch(()=>false);record({stage:'generic-hydration-failed',matches});throw error;}record({stage:'generic-hydrated',explanationMatches:true});
  for(const [label,value]of Object.entries(values)){const handle=await work(()=>admin.evaluateHandle(label=>{const h=[...document.querySelectorAll('h2')].find(e=>e.textContent==='Edit Solution');const rows=[...h.parentElement.parentElement.querySelectorAll('label')].filter(e=>e.textContent.trim()===label);if(rows.length!==1)throw Error('Unique generic field required');return rows[0].parentElement.querySelector('input,textarea');},label));try{await work(()=>replaceEditorTitle(handle.asElement(),value,()=>{}));}finally{await handle.dispose();}}
  const preSave=await work(()=>admin.evaluate(genericEditorMatches,{...values,Explanation:base.explanation}));record({stage:'generic-presave',untouchedExplanationMatches:preSave});assert.equal(preSave,true,'Generic untouched explanation must survive typing');const pending=admin.waitForResponse(r=>decodeURIComponent(new URL(r.url()).pathname)===endpoint&&r.request().method()==='PUT',{timeout:15000});pending.catch(()=>{});
  await work(()=>admin.evaluate(()=>{const h=[...document.querySelectorAll('h2')].find(e=>e.textContent==='Edit Solution');const buttons=[...h.parentElement.parentElement.querySelectorAll('button[type="submit"]')].filter(e=>!e.disabled);if(buttons.length!==1)throw Error('Unique generic submit required');buttons[0].click();}));const response=await work(()=>pending),payload=JSON.parse(response.request().postData());let responseBody=null;try{const text=await work(()=>response.text());if(Buffer.byteLength(text)<=4096)responseBody=JSON.parse(text);}catch{}record(genericSaveDiagnostic(payload,patch,response.status(),responseBody));assert.deepEqual(payload,patch);assert.equal(response.status(),200);await work(()=>admin.waitForFunction(()=>![...document.querySelectorAll('h2')].some(e=>e.textContent==='Edit Solution')));
  const expected={...original,...genericStoredPatch(patch)};assert.deepEqual(await work(()=>read(item)),expected);const listed=(await api(admin,'/api/admin/solutions')).solutions.filter(x=>x.id===item.workshopKey+':'+item.id);assert.equal(listed.length,1);assert.equal(listed[0].title,patch.solution_title);assert.equal(listed[0].description,patch.solution_description);assert.deepEqual(await work(gateSnapshot),gates);
  if(patch===custom){for(let i=0;i<2;i++)await work(()=>require('../../server/database/postgres/workshopPlatformSeed').seedWorkshopPlatform(migration));assert.deepEqual(await work(()=>read(item)),expected);await work(()=>learner.goto(origin+'/workshop/challenges',{waitUntil:'domcontentloaded'}));const label=initial.objectives.find(x=>x.objective_id===item.id).label;await work(()=>learner.waitForFunction(label=>[...document.querySelectorAll('span')].filter(e=>e.textContent===label).length===1,{},label));await work(()=>learner.evaluate(label=>{const e=[...document.querySelectorAll('span')].find(e=>e.textContent===label);const buttons=[...e.parentElement.querySelectorAll('button')].filter(x=>x.textContent.trim()==='Solution');if(buttons.length!==1)throw Error('Unique solution required');buttons[0].click();},label));await work(()=>learner.waitForFunction(value=>{const d=document.querySelector('[role="dialog"][aria-modal="true"]');return d&&[...d.querySelectorAll('h3')].some(e=>e.textContent===value.title)&&d.textContent.includes(value.approach);},{},{title:patch.solution_title,approach:original.approach}));await work(()=>learner.click('[aria-label="Close solution"]'));}
 }
 // The existing generic form materializes optional defaults. Restore original JSON shape,
 // retaining honest instructor provenance rather than pretending the UI omits defaults.
 await work(()=>migration.query('UPDATE workshop_platform.objectives SET solution_content=$3::jsonb WHERE workshop_key=$1 AND objective_id=$2',[item.workshopKey,item.id,JSON.stringify(original)]));assert.deepEqual(await work(()=>read(item)),original);assert.deepEqual(await work(gateSnapshot),gates);
}
async function qualifyObjectiveContent({generic=false,browser,origin,token,adminToken,identity,migration,config,learnerId,siblingId,lab,onCheckpoint=()=>{}}){
 const {bounded,settleOwnership}=require('./secureshopAnalyticsBrowserOwner');
 const contexts=[],began=Date.now(),requests={browser:0,api:0},cases=[];let stage='content-setup';
 const checkpoint=()=>onCheckpoint({stage,requests:{...requests},cases:[...cases]});
 const work=fn=>bounded(Promise.resolve().then(fn),Math.max(1,420000-(Date.now()-began)),'Objective content deadline');
 const selectedCases=generic?[{id:'path_traversal',workshopKey:'legacy_sensitive_file_ssi',challengeKey:'legacy_sensitive_file_ssi'}]:OBJECTIVE_CONTENT_CASES;const familyKeys=selectedCases.map(x=>x.workshopKey);
 const catalogSnapshot=async()=>({exercises:(await identity.query('SELECT workshop_key,is_visible,show_hints,show_solutions FROM workshop_platform.exercises WHERE workshop_key=ANY($1::text[]) ORDER BY workshop_key',[familyKeys])).rows,objectives:(await identity.query('SELECT workshop_key,objective_id,label,is_enabled,hint_enabled,solution_enabled,hint_content,solution_content FROM workshop_platform.objectives WHERE workshop_key=ANY($1::text[]) ORDER BY workshop_key,objective_id',[familyKeys])).rows});
 const durableSnapshot=async()=>({completions:(await identity.query('SELECT to_jsonb(c) row FROM workshop_platform.completions c WHERE user_id=ANY($1::bigint[]) ORDER BY user_id,workshop_key,objective_id',[[learnerId,siblingId]])).rows,lab:(await lab.query('SELECT to_jsonb(p) row FROM supply_chain.progress p WHERE user_id=ANY($1::text[]) ORDER BY user_id,objective_id',[[String(learnerId),String(siblingId)]])).rows});
 const initial=await work(catalogSnapshot),durable=await work(durableSnapshot);assert.equal(initial.exercises.length,selectedCases.length);assert(durable.lab.some(x=>String(x.row.user_id)===String(siblingId)));assert.equal(durable.completions.length,0);
 const read=async item=>(await identity.query('SELECT solution_content FROM workshop_platform.objectives WHERE workshop_key=$1 AND objective_id=$2',[item.workshopKey,item.id])).rows[0].solution_content;
 const gateSnapshot=async()=>{const data=await catalogSnapshot();return {exercises:data.exercises,objectives:data.objectives.map(({hint_content,solution_content,...rest})=>rest)};};
 async function page(tokenValue){const context=await browser.createBrowserContext();contexts.push(context);const page=await context.newPage();await configureFreshPage(page);await page.evaluateOnNewDocument(t=>localStorage.setItem('token',t),tokenValue);await page.setRequestInterception(true);page.on('request',r=>{requests.browser++;(objectiveContentRequestAllowed(r.url(),origin,requests.browser)?r.continue():r.abort()).catch(()=>{});});return page;}
 async function api(page,url){assert(++requests.api<=40);const r=await work(()=>page.evaluate(async url=>{const r=await fetch(url,{headers:{Authorization:'Bearer '+localStorage.getItem('token')}});return {status:r.status,body:await r.json()};},url));assert.equal(r.status,200);checkpoint();return r.body;}
 try{
  for(const item of selectedCases){assert(require('../../server/config/workshopCatalog').WORKSHOP_OBJECTIVES[item.workshopKey].some(x=>x.id===item.id));await work(()=>config.setExerciseVisibility(item.workshopKey,true,learnerId));await work(()=>config.setObjectiveVisibility(item.workshopKey,item.id,true,learnerId));await work(()=>config.setMasterSolutionVisibility(item.workshopKey,true,learnerId));}
  const learner=await work(()=>page(token)),admin=await work(()=>page(adminToken));await work(()=>admin.goto(origin+'/admin/exercises',{waitUntil:'domcontentloaded'}));
  for(const item of selectedCases){
   stage=item.id+':open';checkpoint();await work(()=>admin.evaluate(require('./mcpAuditContentBrowser').closeAdminDialogs));await work(()=>admin.waitForFunction(require('./mcpAuditContentBrowser').adminDialogsClosed));
   const card='[data-exercise-key="'+item.challengeKey+'"]';await work(()=>admin.waitForSelector(card));await work(()=>admin.$eval(card,e=>{const matches=[...e.querySelectorAll('button')].filter(b=>b.textContent.includes('Manage Objectives'));if(matches.length!==1)throw Error('Unique objective control required');matches[0].click();}));
   if(generic){await qualifyGenericSolutionCase({item,admin,learner,origin,work,read,gateSnapshot,api,migration,initial,record:diagnostic=>onCheckpoint({stage:item.id+':save-response',requests:{...requests},cases:[...cases],diagnostic})});cases.push({id:item.id,workshopKey:item.workshopKey,typedSave:true,readback:true,learnerProjection:true,reseedPreserved:true,restored:true});checkpoint();continue;}
   const original=await work(()=>read(item)),savedGates=await work(gateSnapshot);for(const key of Object.keys(OBJECTIVE_CONTENT_FIELDS))assert.equal(typeof original[key],'string');
   const custom={title:'Owned '+item.id+' title',hint:'Owned '+item.id+' hint',example:'Owned '+item.id+' example <b>literal</b>',explanation:'Owned '+item.id+' explanation'};
   const preview='/api/admin/'+item.route+'/objective-solutions/preview/'+item.id,endpoint='/api/admin/'+item.route+'/objective-solutions/'+item.id;
   for(const values of [custom,Object.fromEntries(Object.keys(OBJECTIVE_CONTENT_FIELDS).map(key=>[key,original[key]]))]){
    stage=item.id+':typed-save';checkpoint();const selector='[data-objective-id="'+item.id+'"] button[title="Edit Solution"]';await work(()=>admin.waitForSelector(selector,{visible:true}));await work(()=>admin.$eval(selector,e=>e.scrollIntoView({block:'center',inline:'center'})));await work(()=>admin.waitForFunction(editorTargetUnobstructed,{},selector));await work(()=>admin.click(selector));
    await work(()=>admin.waitForFunction(objectiveContentEditorMatches,{},{id:item.id,values:Object.fromEntries(Object.keys(OBJECTIVE_CONTENT_FIELDS).map(key=>[key,values===custom?original[key]:custom[key]]))}));
    for(const [key,label] of Object.entries(OBJECTIVE_CONTENT_FIELDS)){const handle=await work(()=>admin.evaluateHandle(({id,label})=>{const headings=[...document.querySelectorAll('h2')].filter(e=>e.textContent==='Edit Objective Solution — '+id);if(headings.length!==1)throw Error('Unique editor required');const fields=[...headings[0].parentElement.parentElement.querySelectorAll('label')].filter(e=>e.textContent===label);if(fields.length!==1)throw Error('Unique field required');return fields[0].parentElement.querySelector('input,textarea');},{id:item.id,label}));try{await work(()=>replaceEditorTitle(handle.asElement(),values[key],()=>{}));}finally{await handle.dispose();}}
    await work(()=>admin.waitForFunction(objectiveContentEditorMatches,{},{id:item.id,values}));const waiting=admin.waitForResponse(r=>new URL(r.url()).pathname===endpoint&&r.request().method()==='POST',{timeout:15000});waiting.catch(()=>{});
    await work(()=>admin.evaluate(id=>{const h=[...document.querySelectorAll('h2')].find(e=>e.textContent==='Edit Objective Solution — '+id);const buttons=[...h.parentElement.parentElement.querySelectorAll('button')].filter(e=>e.textContent==='Save Changes'&&!e.disabled);if(buttons.length!==1)throw Error('Unique save required');buttons[0].click();},item.id));const response=await work(()=>waiting);assert.equal(response.status(),200);assertObjectiveContentPatch(JSON.parse(response.request().postData()),values);
    await work(()=>admin.waitForFunction(id=>![...document.querySelectorAll('h2')].some(e=>e.textContent==='Edit Objective Solution — '+id),{},item.id));const expected={...original,...values};assert.deepEqual(await work(()=>read(item)),expected);assert.deepEqual((await api(admin,preview)).solution,{objective_id:item.id,...expected});assert.deepEqual(await work(gateSnapshot),savedGates);
    if(values===custom){
     stage=item.id+':reseed';checkpoint();const seed=require('../../server/database/postgres/workshopPlatformSeed');await work(()=>seed.seedWorkshopPlatform(migration));await work(()=>seed.seedWorkshopPlatform(migration));assert.deepEqual(await work(()=>read(item)),expected);assert.deepEqual(await work(gateSnapshot),savedGates);
     stage=item.id+':learner';checkpoint();await work(()=>learner.goto(origin+'/workshop/challenges',{waitUntil:'domcontentloaded'}));const label=initial.objectives.find(x=>x.workshop_key===item.workshopKey&&x.objective_id===item.id).label;
     await work(()=>learner.waitForFunction(label=>[...document.querySelectorAll('span')].filter(e=>e.textContent===label).length===1,{},label));
     await work(()=>learner.evaluate(label=>{const labels=[...document.querySelectorAll('span')].filter(e=>e.textContent===label);if(labels.length!==1)throw Error('Unique learner objective required');const buttons=[...labels[0].parentElement.querySelectorAll('button')].filter(e=>e.textContent.trim()==='Solution');if(buttons.length!==1)throw Error('Unique learner solution required');buttons[0].click();},label));await work(()=>learner.waitForFunction(objectiveContentModalMatches,{},custom));await work(()=>learner.click('[aria-label="Close solution"]'));
    }
   }
   cases.push({id:item.id,workshopKey:item.workshopKey,typedSave:true,readback:true,learnerProjection:true,reseedPreserved:true,restored:true});checkpoint();
  }
  for(const row of initial.objectives)await work(()=>migration.query('UPDATE workshop_platform.objectives SET is_enabled=$3,hint_enabled=$4,solution_enabled=$5 WHERE workshop_key=$1 AND objective_id=$2',[row.workshop_key,row.objective_id,row.is_enabled,row.hint_enabled,row.solution_enabled]));
  for(const row of initial.exercises)await work(()=>migration.query('UPDATE workshop_platform.exercises SET is_visible=$2,show_hints=$3,show_solutions=$4 WHERE workshop_key=$1',[row.workshop_key,row.is_visible,row.show_hints,row.show_solutions]));
  assert.deepEqual(await work(catalogSnapshot),initial);assert.deepEqual(await work(durableSnapshot),durable);assert(requests.browser<=400);assert(requests.api<=40);
  return {cases,requests,siblingPreserved:true,gatesPreserved:true,contentRestored:true};
 }finally{const closed=await settleOwnership(contexts.map((c,i)=>['context'+i,()=>c.close()]),5000);assert(closed.every(x=>x.status==='fulfilled'),'Content contexts must close');}
}
module.exports={genericSaveDiagnostic,genericSolutionPatch,genericStoredPatch,genericEditorMatches,OBJECTIVE_CONTENT_CASES,objectiveContentRequestAllowed,objectiveContentEditorMatches,objectiveContentModalMatches,assertObjectiveContentPatch,qualifyObjectiveContent,assertFreshDefaults,renderedApproachMatches,qualifyDefaultReseed,IDS,KEY,DPI_EDITOR,assertEditorPatch,project,objectiveRowsMatch,instructorRowsMatch,timeText,aggregateMatches,solutionEditorMatches,safeHttpDiagnostic,appendHttpDiagnostic,clickVisibleEditor,editorTargetUnobstructed,solutionEditorAbsent,configureFreshPage,titleProof,replaceEditorTitle,qualify};
